package main

import (
	"gno.land/r/gov/dao"
	valset "gno.land/r/sys/validators/v0"
)

func main(cur realm) {
	r := valset.NewValidatorProposalRequest(
		cross(cur),
		[]valset.ValoperChange{
			valset.NewValoperChange(address("g1rppw28c4u4h2pmf46q3956uv44zjwapelctsac"), 60),
		},
		"Add valoper lurien to the valset",
		"Add operator g1rppw28c4u4h2pmf46q3956uv44zjwapelctsac (lurien) to the active valset at voting power 60, matching the other members of the set. Profile: /r/gnops/valopers:g1rppw28c4u4h2pmf46q3956uv44zjwapelctsac",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
}
